function rng(){let t=s.rng+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}const rnd=(a,b)=>a+rng()*(b-a),pick=a=>a[Math.floor(rng()*a.length)];
