function ensureCareer(g){if(g.moves&&g.caps){for(const k of ['pierce','combo']){g.moves[k]??=Math.round(3+stableRoll(g,'initial:'+k)*7);g.caps.moves[k]??=personalCap(g,'move:'+k,g.moves[k]);}}if(g.mastery&&g.caps){for(const id of ['bow','crossbow']){g.mastery[id]??=10;g.caps.weapons[id]??=Math.max(g.mastery[id],g.potential||60);}}if(g.caps&&g.mastery&&g.killHistory&&g.moves?.thrust!==undefined&&g.caps.moves.thrust!==undefined&&g.moves.sand!==undefined&&g.caps.moves.sand!==undefined&&g.moves.recover!==undefined&&g.caps.moves.recover!==undefined&&g.moves.rearFinish!==undefined&&g.caps.moves.rearFinish!==undefined&&g.moves.shieldBash!==undefined&&g.caps.moves.shieldBash!==undefined&&g.moves.groundFinish!==undefined&&g.caps.moves.groundFinish!==undefined){delete g.level;delete g.xp;delete g.talents;return g;}ensureIdentity(g);if(!g.mastery){const family=id=>['spear','trident','halberd'].includes(id)?'spear':['shortbow','longbow','sling','gastraphetes'].includes(id)?'bow':['javelin','throwaxe'].includes(id)?'throw':'sword';g.mastery=Object.fromEntries(weaponDefs.map(w=>[w.id,clamp(g.skills?.[family(w.id)]??10,1,100)]))}for(const w of weaponDefs)g.mastery[w.id]??=10;if(g.trainingWeapon&&!weaponDefs.some(w=>w.id===g.trainingWeapon))g.trainingWeapon='short';if(!g.killHistory){g.killHistory=[];g.unrecordedKills=g.kills||0}if(g.retired&&!g.trainerCaps)g.trainerCaps=copy(g.mastery);ensurePotentials(g);return g}
