function combatPractice(g,id,amount=.008){const a=s.battle?.actors.find(a=>a.g.id===g.id);if(a)learn(a,'weapons',id,amount)}
function lesson(g,id=gear(g,'weapon')?.def||'fist'){ensureCareer(g);const teacher=s.trainers.filter(t=>t.retired&&t.trainerEnabled!==false&&t.trainerCaps?.[id]>mastery(g,id)).sort((a,b)=>b.trainerCaps[id]-a.trainerCaps[id])[0];return {id,teacher,cap:teacher?Math.min(teacher.trainerCaps[id],g.caps.weapons[id]):0,rate:teacher?.15:0}}

