if(s.battle){for(const a of s.battle.actors){const w=gear(a.g,'weapon');if(w?.def==='javelin')a.ammo=Math.min(a.ammo,3);if(w?.def==='net')a.ammo=Math.min(a.ammo,1);}s.battle.projectiles=(s.battle.projectiles||[]).filter(p=>!removedWeapons.has(p.snapshot?.w?.id)&&p.kind!==6);for(const a of s.battle.actors){if(!gear(a.g,'weapon')){a.ammo=0;a.wind=0;a.swing=0;a.disarmed=false;}}}
